function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s||'').normalize('NFKC').replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-96)).replace(/[\s\u3000、。，．.!！?？:：;；「」『』【】（）()\[\]・〜～…‥]/g,'').toLowerCase();}
function getScene(){
 const original=DATA.scenes[state.index];
 if(!state.relationshipTier) return adaptedScene(original);
 const tier=RELATIONSHIP_STORIES.tiers[state.relationshipTier-1];
 const story=tier.scenes[state.index];
 return {...original,mitsuya:story.mitsuya,choices:original.choices.map((choice,i)=>({
  ...choice,text:story.choices[i].text,
  reading:story.choices[i].reading,
  response:story.choices[i].response
 }))};
}
function relationshipTier(){return stored.bondLevel||0}
function bondLabel(){return BOND_STEPS[state.relationshipTier||0]}


function formatTime(ms){const sec=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function elapsed(){return state.typingMs+(state.page==='play'&&state.typingStarted?Math.max(0,Date.now()-state.typingStarted):0);}
function speed(){const ms=elapsed();return ms>0?Math.round(state.typedCount/(ms/60000)):0;}
function accuracy(){return state.typedCount?Math.round(100*state.typedCount/(state.typedCount+state.mistakes)):100;}
function rank(){const a=accuracy(),v=speed();if(a>=99&&v>=90)return {label:'S',name:'星の綴り手'};if(a>=97&&v>=65)return {label:'A',name:'静かな名手'};if(a>=94&&v>=40)return {label:'B',name:'ことばの旅人'};if(a>=90&&v>=20)return {label:'C',name:'やさしい訪れ人'};return {label:'D',name:'はじめの一歩'};}
function bestSummary(){return `<div class="recordline">自己ベスト：${stored.bestSpeed||'—'}文字/分 ／ 最長コンボ ${stored.bestCombo||0} ／ 最短 ${stored.bestTime?formatTime(stored.bestTime):'—'}</div>`;}
function typingHUD(){return `<div class="typinghud"><span>✦ コンボ <b>${state.combo}</b> / 最高 ${state.maxCombo}</span><span>正確率 <b>${accuracy()}%</b></span><span>速度 <b>${speed()}文字/分</b></span></div>`;}
function clockUI(){const paused=state.page==='reply';const waiting=state.page==='play'&&!state.typingStarted;return `<span class="gameclock ${paused?'clock-paused':''}" aria-label="タイピング計測時間">⏱ <span id="clockValue">${formatTime(elapsed())}</span>${paused?'<span class="clock-state">⏸ カウントストップ中</span>':waiting?'<span class="clock-state">入力すると計測開始</span>':''}</span>`;}
// Preserve full orthography, or accept kana readings and mixed kanji/kana orthography.
// Romaji is evaluated on each keystroke without relying on Japanese IME confirmation.
// A memoized kana-to-romaji recognizer accepts common alternate spellings without
// materializing exponentially many full-sentence variants.
const ROMA_BASE={
 'あ':['a'],'い':['i'],'う':['u'],'え':['e'],'お':['o'],
 'か':['ka'],'き':['ki'],'く':['ku'],'け':['ke'],'こ':['ko'],
 'さ':['sa'],'し':['shi','si'],'す':['su'],'せ':['se'],'そ':['so'],
 'た':['ta'],'ち':['chi','ti'],'つ':['tsu','tu'],'て':['te'],'と':['to'],
 'な':['na'],'に':['ni'],'ぬ':['nu'],'ね':['ne'],'の':['no'],
 'は':['ha'],'ひ':['hi'],'ふ':['fu','hu'],'へ':['he'],'ほ':['ho'],
 'ま':['ma'],'み':['mi'],'む':['mu'],'め':['me'],'も':['mo'],
 'や':['ya'],'ゆ':['yu'],'よ':['yo'],
 'ら':['ra'],'り':['ri'],'る':['ru'],'れ':['re'],'ろ':['ro'],
 'わ':['wa'],'を':['wo','o'],'ん':['nn','n'],'が':['ga'],'ぎ':['gi'],'ぐ':['gu'],'げ':['ge'],'ご':['go'],
 'ざ':['za'],'じ':['ji','zi'],'ず':['zu'],'ぜ':['ze'],'ぞ':['zo'],
 'だ':['da'],'ぢ':['di','ji'],'づ':['du','zu'],'で':['de'],'ど':['do'],
 'ば':['ba'],'び':['bi'],'ぶ':['bu'],'べ':['be'],'ぼ':['bo'],
 'ぱ':['pa'],'ぴ':['pi'],'ぷ':['pu'],'ぺ':['pe'],'ぽ':['po'],
 'ぁ':['xa','la'],'ぃ':['xi','li'],'ぅ':['xu','lu'],'ぇ':['xe','le'],'ぉ':['xo','lo'],
 'ゃ':['xya','lya'],'ゅ':['xyu','lyu'],'ょ':['xyo','lyo'],
 'っ':['xtu','ltu','xtsu'],'ゔ':['vu'],'ー':['-']
};
const ROMA_YO={
 'き':['ky'],'し':['sh','sy'],'ち':['ch','ty','cy'],'に':['ny'],'ひ':['hy'],'み':['my'],'り':['ry'],
 'ぎ':['gy'],'じ':['j','zy'],'ぢ':['dy'],'び':['by'],'ぴ':['py'],
 'て':['th'],'で':['dh'],'ふ':['fy'],'ゔ':['vy']
};
const ROMA_EXTRA={'しぇ':['she','sye'],'ちぇ':['che','tye'],'じぇ':['je','zye'],
 'てぃ':['thi','ti'],'でぃ':['dhi','di'],'ふぁ':['fa'],'ふぃ':['fi'],'ふぇ':['fe'],'ふぉ':['fo'],
 'うぃ':['wi'],'うぇ':['we'],'うぉ':['who'],'つぁ':['tsa'],'つぃ':['tsi'],'つぇ':['tse'],'つぉ':['tso']};
for(const [kana,bases] of Object.entries(ROMA_YO))for(const [small,vowel] of [['ゃ','a'],['ゅ','u'],['ょ','o']])ROMA_EXTRA[kana+small]=[...new Set(bases.map(base=>base+vowel))];
const KANA_VOWEL={
 'あ':'a','か':'a','さ':'a','た':'a','な':'a','は':'a','ま':'a','や':'a','ら':'a','わ':'a','が':'a','ざ':'a','だ':'a','ば':'a','ぱ':'a','ぁ':'a','ゃ':'a','ゎ':'a',
 'い':'i','き':'i','し':'i','ち':'i','に':'i','ひ':'i','み':'i','り':'i','ぎ':'i','じ':'i','ぢ':'i','び':'i','ぴ':'i','ぃ':'i',
 'う':'u','く':'u','す':'u','つ':'u','ぬ':'u','ふ':'u','む':'u','ゆ':'u','る':'u','ぐ':'u','ず':'u','づ':'u','ぶ':'u','ぷ':'u','ぅ':'u','ゅ':'u','ゔ':'u',
 'え':'e','け':'e','せ':'e','て':'e','ね':'e','へ':'e','め':'e','れ':'e','げ':'e','ぜ':'e','で':'e','べ':'e','ぺ':'e','ぇ':'e',
 'お':'o','こ':'o','そ':'o','と':'o','の':'o','ほ':'o','も':'o','よ':'o','ろ':'o','を':'o','ご':'o','ぞ':'o','ど':'o','ぼ':'o','ぽ':'o','ぉ':'o','ょ':'o'
};
const VOWEL_TO_KANA={a:'あ',i:'い',u:'う',e:'え',o:'お'};
function cleanKana(s){return normalize(s);}
function romajiParts(reading,pos){const c=reading[pos];if(!c)return [];
 if(c==='ー'){
  // Standard Japanese typing uses the physical hyphen key for ー.
  // Repeating the preceding vowel remains accepted as an optional alternative.
  let i=pos-1;while(i>=0&&reading[i]==='ー')i--;
  const vowel=KANA_VOWEL[reading[i]];
  return [{length:1,spellings:vowel?['-',vowel]:['-']}];
 }

 if(c==='っ'){
  const next=romajiParts(reading,pos+1).flatMap(item=>item.spellings).map(x=>x[0]).filter(x=>x&&!/[aeiou]/.test(x));
  return [{length:1,spellings:[...new Set([...ROMA_BASE['っ'],...next])]}];
 }
 if(c==='ん'){
  const after=reading[pos+1];
  // A single n before vowels, y and another n is ambiguous; require nn there.
  const single=after&&!/[あいうえおやゆよなにぬねのん]/.test(after);
  return [{length:1,spellings:single?['nn','n']:['nn']}];
 }
 const parts=[];
 if(ROMA_EXTRA[reading.slice(pos,pos+2)])parts.push({length:2,spellings:ROMA_EXTRA[reading.slice(pos,pos+2)]});
 if(ROMA_BASE[c])parts.push({length:1,spellings:ROMA_BASE[c]});
 return parts;
}
function romaMatch(raw,reading){
 const value=String(raw||'').toLowerCase();const kana=cleanKana(reading);
 if(!/^[a-z-]*$/.test(value))return {valid:false,complete:false,progress:0};
 const memo=new Map();
 function walk(k,v){const key=k+':'+v;if(memo.has(key))return memo.get(key);
  if(v===value.length){const r={valid:true,complete:k===kana.length};memo.set(key,r);return r;}
  if(k>=kana.length){const r={valid:false,complete:false};memo.set(key,r);return r;}
  for(const item of romajiParts(kana,k))for(const spelling of item.spellings){
   const remaining=value.slice(v);
   if(remaining.length<spelling.length&&spelling.startsWith(remaining)){const r={valid:true,complete:false};memo.set(key,r);return r;}
   if(remaining.startsWith(spelling)){
    const found=walk(k+item.length,v+spelling.length);
    if(found.valid){memo.set(key,found);return found;}
   }
  }
  const r={valid:false,complete:false};memo.set(key,r);return r;
 }
 const r=walk(0,0);
 return {...r,progress:r.valid?Math.min(99,Math.round(value.length/Math.max(1,romanize(kana).length)*100)):0};
}
function romanize(reading){const kana=cleanKana(reading);let text='';for(let i=0;i<kana.length;){const parts=romajiParts(kana,i);if(parts.length){text+=parts[0].spellings[0];i+=parts[0].length;}else{i++;}}return text;}
function matchCandidates(raw){return getScene().choices.flatMap((c,i)=>romaMatch(raw,c.reading).valid?[i]:[]);}
function isComplete(raw,choice){return raw.length>0&&romaMatch(raw,choice.reading).complete;}
function longestProgress(raw,choice){return romaMatch(raw,choice.reading).progress;}
function settingsUI(){return `<div class="modebox"><div class="modelabel">入力方法 <small>ローマ字タイピング</small></div><p class="modehelp">漢字変換やEnterでの確定は不要。英字で打つと1キーごとに判定します。<code>shi / si</code>、<code>tsu / tu</code> などの入力も対応。日本語IMEがONの場合は英字入力に切り替えてね。</p></div>`;}
function situationUI(){const a=state.relationshipTier?(()=>{const t=RELATIONSHIP_STORIES.tiers[state.relationshipTier-1].scenes[state.index];return [t.situation,t.point,SITUATIONS[state.index][2]]})():SITUATIONS[state.index];return `<div class="situation"><span class="situation-tag">${state.relationshipTier?'CHAPTER '+(state.relationshipTier+1)+' · '+esc(bondLabel()):state.revisit?'REVISIT · 前回ランク '+esc(state.rankLevel):'SCENE'} / ${esc(getScene().location)}</span><p>${esc(a[0])}</p><div class="situation-question">${esc(a[1])}</div></div>`;}
function lessonUI(){return `<details class="lesson"><summary>この場面のヒントを見る <span>INFJ × コミュニケーション</span></summary><p>${esc(SITUATIONS[state.index][2])}</p><small>MBTIは人の性格や行動を確定するものではありません。ここでの反応は架空の「みつや」のものです。</small></details>`;}

const VIDEO_PREF_KEY='mitsuya_video_autoshow_v20';
let autoVideo=(()=>{try{return localStorage.getItem(VIDEO_PREF_KEY)!=='off'}catch{return true}})();
let shownVideosThisRun=new Set();
function unlockVideo(id){stored.seenVideos=stored.seenVideos||[];if(!stored.seenVideos.includes(id)){stored.seenVideos.push(id);persist();}}
function migratedSeenVideos(){const ids=new Set(stored.seenVideos||[]);for(const id of stored.unlocked||[])if(ENDING_MEDIA[id])ids.add(id);for(const id of stored.bondEndings||[])if(ENDING_MEDIA[id])ids.add(id);if((stored.bondEndings||[]).includes('HAPPY_CLOSENESS_0'))ids.add('HAPPY_CLOSENESS');if(stored.plays>0)ids.add('INTRO');if(stored.plays>1)ids.add('WELCOME_BACK');return ids;}
function setAutoVideo(value){autoVideo=!!value;try{localStorage.setItem(VIDEO_PREF_KEY,autoVideo?'on':'off')}catch{}render();}
function eventVideo(id){return EVENT_VIDEO_LIBRARY.find(x=>x.id===id);}
function eventCandidate(){if(state.page!=='play')return null;
 const i=state.index,t=state.relationshipTier,s=state.stats;
 if(i===0)return state.revisit?'WELCOME_BACK':'INTRO';
 if(i===1 && t>=1)return 'MEET_AGAIN';
 if(i===2 && t>=1)return 'FIRST_LAUGH';
 if(i===3 && t>=2)return 'SECRET_NOTE';
 if(i===4 && t>=2)return 'VULNERABLE';
 if(i===5 && t>=2)return 'WEEKEND_STROLL';
 if(i===6 && t>=2)return 'CASUAL_NAME';
 if(i===7 && t>=3)return 'CORE_SECRET';
 if(i===8 && t>=3)return 'MY_TURN';
 if(i===8 && (state.flags.pressure>=2 || state.flags.mask>=2 || s.safety<=8))return 'UNSPOKEN';
 if(i===8 && s.resonance>=23)return 'SAME_STARS';
 if(i===8 && s.safety>=23)return 'QUIET_TIME';
 return null;
}
function showEventIfNeeded(){const id=eventCandidate();if(!id||shownVideosThisRun.has(id))return;shownVideosThisRun.add(id);unlockVideo(id);if(autoVideo)openVideoLightbox(eventVideo(id));}
function openVideoLightbox(v){if(!v)return;const h=document.querySelector('#lightbox-host');
 const poster=state.page==='play'||state.page==='reply'?sceneArt().src:face();
 h.innerHTML=`<div class="lightbox story-video-modal" role="dialog" aria-modal="true" aria-label="${esc(v.title)}"><div class="story-video-wrap"><span class="kicker">MITSUYA · ${esc(v.chapter)}</span><h2>${esc(v.title)}</h2><video id="story-player" controls autoplay playsinline preload="metadata" poster="${esc(poster)}"><source src="${esc(v.url)}" type="video/mp4">動画を再生できません。</video><p class="small">⏸ カウントストップ中　／　動画はスキップしても「みつやの思い出」に保存されます。</p><div class="btnrow"><button class="button" id="video-skip">スキップして続ける →</button><button class="button alt" id="video-close">閉じる</button></div></div></div>`;
 function close(){const p=h.querySelector('video');if(p)p.pause();h.innerHTML='';if(state.page==='play')document.querySelector('#typing')?.focus({preventScroll:true});}
 h.querySelector('#video-skip').onclick=close;h.querySelector('#video-close').onclick=close;
 h.querySelector('#story-player').addEventListener('ended',()=>{h.querySelector('#video-skip').textContent='続ける →';});
 h.querySelector('video').play().catch(()=>{});
}
function videoLibrary(){const unlocked=migratedSeenVideos();const endings=Object.entries(ENDING_MEDIA).map(([id,url])=>{const parent=id.startsWith('HAPPY_CLOSENESS')?'HAPPY_CLOSENESS':id;const e=ENDINGS.find(x=>x.id===parent);return {id,url,title:parent==='HAPPY_CLOSENESS'?'親密エンド '+(id===parent?'Lv1':'Lv'+(Number(id.slice(-1))+1)):(e?.title||id),chapter:'エンディング',hint:'この結末にたどり着くと解放'};});return [...EVENT_VIDEO_LIBRARY,...endings].map(v=>({...v,unlocked:unlocked.has(v.id)}));}
function videosPage(){const list=videoLibrary();const n=list.filter(x=>x.unlocked).length;return `<div class="kicker">MITSUYA · VIDEO MEMORIES</div><h1 class="resulttitle">みつやの思い出</h1><p class="introcopy">途中の動画を見なくても、物語は進められるよ。見逃した場面は、ここからいつでも。</p><div class="bond-info"><strong>動画の思い出 ${n} / ${list.length}</strong><p>一度解放した動画は、途中でスキップしてもここから再生できます。未解放の動画はタイトルと映像を隠してあります。</p></div><div class="video-memory-grid">${list.map(v=>`<button type="button" class="video-memory-card ${v.unlocked?'':'is-locked'}" ${v.unlocked?`data-memory="${esc(v.id)}"`:'disabled'}><span class="memory-kind">${v.unlocked?esc(v.chapter):'LOCKED'}</span><strong>${v.unlocked?esc(v.title):'まだ知らない物語'}</strong><small>${v.unlocked?'▶ 再生する':'物語の中で出会うと解放'}</small></button>`).join('')}</div><div class="btnrow"><button class="button alt" id="home">タイトルへ</button><button class="button alt" id="gallery">エンディング一覧</button></div><div class="backup-tools"><button type="button" class="button alt" id="save-export">思い出をバックアップ</button><label class="button alt backup-import">バックアップを読み込む<input id="save-import" type="file" accept="application/json,.json" hidden></label></div>${storageNotice()}`;}
function exportSave(){const payload={app:'mitsuya-typing',version:1,createdAt:new Date().toISOString(),data:stored};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mitsuya-omoidetecho-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function importSave(file){if(!file)return;try{if(file.size>1024*1024)throw Error('ファイルが大きすぎます');const input=JSON.parse(await file.text());if(input.app!=='mitsuya-typing'||input.version!==1||!input.data||!Array.isArray(input.data.unlocked)||!Array.isArray(input.data.seenVideos)||!Array.isArray(input.data.seenArt))throw Error('みつやのバックアップファイルではありません');if(!confirm('現在の思い出をバックアップ内容で置き換えます。続けますか？'))return;localStorage.setItem(KEY,JSON.stringify(input.data));stored=readStore();state=initial();render();alert('思い出を復元しました');}catch(err){alert('読み込めませんでした：'+err.message);}}
function storageNotice(){return `<details class="storage-notice"><summary>思い出が消えるのはどんなとき？</summary><p>このゲームは進行記録を、今使っているブラウザの「サイトデータ（localStorage）」に保存しています。Cookieを含むサイトデータの削除、プライベートブラウズの終了、ブラウザや端末の変更などで、解放記録が使えなくなる場合があります。</p><p>通常の画像キャッシュの削除だけでは、必ずしも消えません。ログインによる端末間同期はありません。ページ下部のバックアップを保存しておけば、後から読み込んで復元できます。</p><p>すべての記録を消したい場合、ブラウザ側でこのサイトの保存データを削除してください。</p></details>`;}

function startRun(){shownVideosThisRun=new Set();const wasPlayed=stored.plays>0;const previousRank=stored.lastRank||'D';state=initial();state.revisit=wasPlayed;state.rankLevel=previousRank;state.relationshipTier=relationshipTier();state.runArtChapter=stored.plays%7;state.page='play';revealSceneArt();state.runStarted=Date.now();render();showEventIfNeeded();}
function tick(){const el=document.getElementById('clockValue');if(el)el.textContent=formatTime(elapsed());}

function displayMood(){if(state.page==='result'){return state.ending.type==='bad'?'shadow':state.ending.theme==='warm'?'warm':'normal'}let x=state.stats;if(state.flags.pressure>=3||state.flags.mask>=3||x.safety<=5||x.resonance<=5)return 'shadow';if(x.safety<=9||x.resonance<=9)return 'uneasy';if(x.safety>=19 && x.closeness>=17)return 'warm';return 'normal'}
function sceneArt(){return SCENE_ART_LIBRARY[(state.runArtChapter*10+state.index)%SCENE_ART_LIBRARY.length];}
function revealSceneArt(){if(state.page!=='play'&&state.page!=='reply')return;const a=sceneArt();stored.seenArt=stored.seenArt||[];if(!stored.seenArt.includes(a.id)){stored.seenArt.push(a.id);persist();}}
function face(){if(state.page==='play'||state.page==='reply')return sceneArt().src;if(state.page==='gallery'||state.page==='album')return SCENE_ART_LIBRARY[Math.max(0,(stored.plays-1)*10)%70].src;if(state.page==='result')return ART[state.ending.id]||ART.normal;return SCENE_ART_LIBRARY[(stored.plays*10)%70].src;}
function stepper(){return `<div class="steps" aria-label="${state.index+1} / ${DATA.scenes.length}">${DATA.scenes.map((_,i)=>`<span class="step ${i<=state.index?'active':''}"></span>`).join('')}</div>`}
function statBars(){return `<div class="metrics">${Object.entries(STATLABEL).map(([k,n])=>`<div class="metric">${n}<div class="meter"><span style="width:${Math.max(1,Math.min(100,state.stats[k]/40*100))}%"></span></div></div>`).join('')}</div>`}
function place(){if(state.page==='play'||state.page==='reply')return getScene().location;return '雨の日、言葉が帰る場所'}
function setVisual(){let f=face(),m=displayMood();game.className=`shell tone-${m}`;visual.innerHTML=`<img src="${esc(f)}" alt="物語の景色にいる銀白の髪のみつや"><div class="visual-head">YADORIGI / MITSUYA</div><div class="visual-foot"><span class="ey">a quiet place for your words</span><div class="person">宿木みつや</div><div class="place">${esc(place())}</div></div>`;}
function baseTop(){return `<div class="top"><span>ことば ${String(state.index+1).padStart(2,'0')} / ${DATA.scenes.length}</span><div class="topright">${clockUI()}${stepper()}</div></div>`}
function render(){setVisual();if(state.page==='home')view.innerHTML=home();else if(state.page==='play')view.innerHTML=play();else if(state.page==='reply')view.innerHTML=reply();else if(state.page==='result')view.innerHTML=result();else if(state.page==='gallery')view.innerHTML=gallery();else if(state.page==='album')view.innerHTML=album();else if(state.page==='videos')view.innerHTML=videosPage();bind();if(state.page==='play'){const inp=document.querySelector('#typing');inp.focus({preventScroll:true});inp.value=state.raw;paintInput();}}
function home(){return `<div class="homehero"><div class="kicker">INFJ × STORY TYPING</div><h1 class="home-title">みつやと綴る、<br>やさしいタイピング</h1><p class="home-lead">言葉を選ぶことは、相手を知ること。<br>10の場面でみつやに返事を綴りながら、タイピングの速さと正確さを磨いていく、小さな物語ゲーム。2周目以降は前回ランクで言葉が変わり、訪れる景色も毎回変わります。ローマ字で1キーずつ判定するので、漢字変換は不要です。</p></div><div class="homefeatures"><div><span>01 · CHOOSE</span><strong>3つの返答から打ち始める</strong><p>マウスで選択する必要なし。言葉を最後まで打つと物語が動き出す。</p></div><div><span>02 · UNDERSTAND</span><strong>INFJをテーマにした対話</strong><p>沈黙、考えすぎ、心の距離。みつやの気持ちを通して相手との接し方を考える。</p></div><div><span>03 · IMPROVE</span><strong>タイピングの上達を記録</strong><p>時間、正確率、自己ベスト、コンボ、ランクを記録。結末の美しい画像も集めよう。</p></div></div><div class="bond-info"><strong>ふたりの距離：${esc(BOND_STEPS[stored.bondLevel||0])}</strong><p>次に会ったときは、これまでの会話を覚えたみつやが少しずつ心を開きます。全4段階。秘密や悩みは安心できる会話を重ねたときに解放されます。</p><span>今までに深まった会話 ${stored.bondWins||0} 回 / 想い出 ${stored.unlocked.length} 種類</span></div>${settingsUI()}<p class="small">${stored.plays>0?'次のプレイは前回の'+esc(stored.lastRank||'D')+'ランクに合わせた再訪編です。':'初回は基本編。2周目から前回ランクに応じた文章に変わります。'}</p>${bestSummary()}<div class="btnrow"><button class="button primary-start" id="start">物語をはじめる　↵</button><button class="button alt" id="gallery">エンディングを見る（${stored.unlocked.length}/8）</button><button class="button alt" id="album">風景アルバム（${(stored.seenArt||[]).length}/70）</button><button class="button alt" id="videos">▶ みつやの思い出（${videoLibrary().filter(x=>x.unlocked).length}/25）</button></div><div class="video-pref"><label><input type="checkbox" id="auto-video" ${autoVideo?"checked":""}> 物語の途中で動画を表示する</label><p>OFFなら自動表示されません。スキップしても解放記録が残るので、「みつやの思い出」から後で視聴できます。</p></div><div class="backup-tools"><button type="button" class="button alt" id="save-export">思い出をバックアップ</button><label class="button alt backup-import">バックアップを読み込む<input id="save-import" type="file" accept="application/json,.json" hidden></label></div>${storageNotice()}<p class="small">返答の内容で物語が変化します。タイピングの速さは親密度に影響しません。<br>INFJはMBTIの分類のひとつで、すべての人に当てはまる攻略法ではありません。</p>`}

function play(){const s=getScene();return `${baseTop()}<div class="scene-row"><div class="kicker">${esc(s.title)} / INFJ MITSUYA</div><button type="button" class="stop-btn" id="stop" aria-label="ゲームを中断してタイトルに戻る">中断する ×</button></div>${situationUI()}<h1 class="maincopy scene-message">${esc(s.mitsuya)}</h1><p class="instruction scene-instruction">3つの中から、今の気持ちに近い返事を<strong>ローマ字で打ってね。</strong> 序盤は短い言葉から。変換・Enter不要で、自動選択されるよ。</p><div class="choices" id="choices">${s.choices.map((c,i)=>`<div class="choice" data-option="${i}"><div class="line"><span class="no">0${i+1}</span><span class="sentence">${esc(c.text)}</span></div><div class="read">${esc(c.reading)}</div><div class="romaji-example">${esc(romanize(c.reading))}</div><div class="mini-progress"><b></b></div></div>`).join('')}</div><div class="inputarea"><label class="inputlabel" for="typing">YOUR WORDS / 返したい言葉を入力</label><input id="typing" class="typefield" type="text" inputmode="latin" lang="en" autocapitalize="off" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="ローマ字で入力（例：kiminope-suo）"><div class="inputnote"><span>ローマ字入力・変換不要・スペース不要・長音「ー」は右上の - キー（例：pe-su / no-to）。母音重ねもOK</span><span id="typingstatus">まだ決まっていません</span></div><div class="error" id="inputerror" aria-live="polite"></div></div><div class="compact-bottom">${typingHUD()}${statBars()}</div>`}

function allMatches(raw){return matchCandidates(raw);}
function matchingLength(raw,choice){return longestProgress(raw,choice);}
function paintInput(){let inp=document.querySelector('#typing');if(!inp)return;let matches=allMatches(state.raw);state.matches=matches;let text=state.raw.toLowerCase(),complete=null;
 getScene().choices.forEach((c,i)=>{const el=document.querySelector(`[data-option="${i}"]`);if(!el)return;let active=matches.includes(i),single=matches.length===1&&active,percentage=active?matchingLength(state.raw,c):0;el.classList.toggle('dim',!!text&&!active);el.classList.toggle('single',!!text&&single);el.querySelector('.mini-progress b').style.width=percentage+'%';if(active&&isComplete(state.raw,c))complete=i;});
 document.querySelector('#typingstatus').textContent=text?matches.length===0?'候補がありません':matches.length===1?'候補がひとつに絞られました':`${matches.length}つの候補が一致しています`:'まだ決まっていません';
 document.querySelector('#inputerror').textContent=text&&matches.length===0?'どの返事にも一致していないみたい。少し戻してみてね。':'';
 if(complete!==null&&!compositionActive&&matches.length===1){finishChoice(complete);}
}
function handleTyping(){if(document.querySelector('#lightbox-host .story-video-modal'))return;const inp=document.querySelector('#typing');if(!inp)return;inp.value=inp.value.toLowerCase().replace(/[^a-z-]/g,'');const before=state.raw;const oldMatches=matchCandidates(before);const newMatches=matchCandidates(inp.value);if(state.typingStarted===0&&inp.value)state.typingStarted=Date.now();if(inp.value&&newMatches.length===0&&oldMatches.length>0){state.mistakes++;state.sceneMistakes++;state.combo=0;}state.raw=inp.value;paintInput()}
function finishChoice(i){if(state.page!=='play')return;const c=getScene().choices[i];state.stats=Object.fromEntries(Object.entries(state.stats).map(([k,v])=>[k,Math.max(0,Math.min(40,v+(c.delta[k]||0)))]));for(const f of c.flags||[])state.flags[f]=(state.flags[f]||0)+1;state.history.push({scene:getScene().id,choice:c.id,text:c.text});state.typedCount+=state.raw.length;if(state.sceneMistakes===0){state.combo++;state.maxCombo=Math.max(state.maxCombo,state.combo);}else{state.combo=0;}state.sceneMistakes=0;if(state.typingStarted){state.typingMs+=Date.now()-state.typingStarted;state.typingStarted=0;}state.reply=c;state.page='reply';render()}
function reply(){let c=state.reply;return `${baseTop()}<div class="kicker">YOUR WORDS / 届いた言葉</div><div class="quoteBox"><p class="replyletter">${esc(c.text)}</p></div><div class="kicker">MITSUYA REPLIES</div><p class="maincopy">${esc(c.response)}</p><p class="introcopy">返した言葉の温度が、次の景色を少し変えていく。<br>この画面の読書・解説時間はタイピング計測に含まれません。</p>${lessonUI()}${typingHUD()}<p class="enterhint">↵ Enterキーで次の会話へ　<button type="button" class="stop-btn stop-inline" id="stop">中断してタイトルへ ×</button></p><div class="performance">${clockUI()} <span>打鍵した文字 ${state.typedCount}</span></div>${statBars()}<div class="btnrow"><button class="button" id="next">${state.index===DATA.scenes.length-1?'結末を見届ける':'次の会話へ'}　→</button></div>`}
function chooseEnding(){let stats=state.stats,flag=state.flags,total=Object.values(stats).reduce((a,b)=>a+b,0);if(flag.pressure>=3)return ENDINGS.find(e=>e.id==='BAD_03');if(flag.mask>=3)return ENDINGS.find(e=>e.id==='BAD_02');if(stats.safety<=5||stats.resonance<=5)return ENDINGS.find(e=>e.id==='BAD_01');if(flag.insight>=7&&total>=75&&stats.safety>=22)return ENDINGS.find(e=>e.id==='SECRET');if(stats.resonance>=26&&total>=60)return ENDINGS.find(e=>e.id==='HAPPY_RESONANCE');if(stats.safety>=26&&total>=60)return ENDINGS.find(e=>e.id==='HAPPY_SAFETY');if(stats.closeness>=24&&total>=60)return ENDINGS.find(e=>e.id==='HAPPY_CLOSENESS');return ENDINGS.find(e=>e.id==='NORMAL')}
function showEnd(){state.runEnded=Date.now();state.ending=chooseEnding();state.page='result';stored.plays++;stored.lastRank=rank().label;
 const lastBond=state.history.filter(x=>x.choice==='A').length;
 const safeEnding=!state.ending.id.startsWith('BAD_');
 if(safeEnding && state.stats.closeness>=22 && state.stats.safety>=19 && lastBond>=5){
  stored.bondWins=(stored.bondWins||0)+1;
  stored.bondPoints=(stored.bondPoints||0)+Math.min(12,lastBond);
  if(stored.bondLevel<3 && stored.bondWins>=stored.bondLevel+1 && stored.bondPoints>=(stored.bondLevel+1)*6)stored.bondLevel++;
 }
 stored.bondEndings=stored.bondEndings||[];
 if(state.ending.id==='HAPPY_CLOSENESS' || state.ending.id==='SECRET'){
   const memory='HAPPY_CLOSENESS_'+(state.relationshipTier||0);
   if(!stored.bondEndings.includes(memory))stored.bondEndings.push(memory);
 }
 if(!stored.unlocked.includes(state.ending.id))stored.unlocked.push(state.ending.id);unlockVideo(state.ending.id==='HAPPY_CLOSENESS'?(state.relationshipTier?'HAPPY_CLOSENESS_'+state.relationshipTier:'HAPPY_CLOSENESS'):state.ending.id);if(state.stats.closeness>=20&&!state.ending.id.startsWith('BAD_'))unlockVideo('SEE_YOU_TOMORROW');stored.best=Math.max(stored.best,state.typedCount);stored.bestSpeed=Math.max(stored.bestSpeed,speed());stored.bestCombo=Math.max(stored.bestCombo,state.maxCombo);stored.bestAccuracy=Math.max(stored.bestAccuracy,accuracy());const t=elapsed();if(!stored.bestTime||t<stored.bestTime)stored.bestTime=t;persist();render()}
function endingArtwork(e){const img=`<img class="resultImage" id="open-result" src="${esc(ART[e.id])}" alt="エンディング『${esc(e.title)}』の特別イラスト">`;const movie=e.id==='HAPPY_CLOSENESS'&&(state.relationshipTier||0)>0?(ENDING_MEDIA[e.id+'_'+state.relationshipTier]||ENDING_MEDIA[e.id]):ENDING_MEDIA[e.id];if(!movie)return img;return `<video class="resultVideo" controls playsinline preload="metadata" poster="${esc(ART[e.id])}"><source src="${esc(movie)}" type="video/mp4">動画を再生できません。</video><p class="small">▶ みつやからの音声メッセージ付きエンディング。再生せずに下へ進むこともできます。</p>`;}
function result(){const e=state.ending;const r=rank();const isClose=e.id==='HAPPY_CLOSENESS';const tierTitle=isClose?(state.relationshipTier===3?'特別な存在':state.relationshipTier===2?'本音の約束':state.relationshipTier===1?'心を開く':'そっと近づく'):e.title;return `<div class="kicker">A MEMORY UNLOCKED · ${e.type.toUpperCase()}</div><h1 class="resulttitle">${esc(tierTitle)}</h1><p class="small">${esc(e.reward)}</p>${endingArtwork(e)}<div class="quoteBox"><p class="replyletter" style="font-size:20px">${esc(isClose?['「……君と話してると、安心する。もう少しだけ、ここにいてもいい？」','「……また会えた。実は、今日を楽しみにしてたんだ。」','「君にはさ、弱いところも見せていい気がする。」','「もう隠さない。……君のこと、大好きだよ。」'][Math.min(3,state.relationshipTier||0)]:(ENDING_VIDEO_LINES[e.id]||e.line))}</p></div><div class="grade"><span class="gradeletter">${r.label}</span><div><b>${r.name}</b><p>速度・正確率で決まるタイピングランク。みつやとの親密度とは無関係。</p></div></div><div class="recordgrid"><div>タイピング計測時間<strong>${formatTime(elapsed())}</strong></div><div>文字/分<strong>${speed()}</strong></div><div>正確率<strong>${accuracy()}%</strong></div><div>最高コンボ<strong>${state.maxCombo}</strong></div><div>入力ミス<strong>${state.mistakes}回</strong></div><div>入力した文字<strong>${state.typedCount}</strong></div></div>${bestSummary()}<div class="bond-info"><strong>ふたりの距離：${esc(BOND_STEPS[stored.bondLevel||0])}</strong><p>${(stored.bondLevel||0)>(state.relationshipTier||0)?'新しい会話が解放されました。次のプレイでは、みつやが今まで話さなかったことを打ち明けてくれます。':'同じ結末でも、ふたりの間に積み重なる物語があります。'}</p></div><p class="small">獲得した思い出 ${stored.unlocked.length}/8。各結末で音声付き動画を再生できます（通信環境が必要です）。</p>${statBars()}<div class="btnrow"><button class="button" id="save">画像を保存</button><button class="button alt" id="again">もう一度話す</button><button class="button alt" id="gallery">ギャラリー</button><button class="button alt" id="videos">▶ 動画の思い出</button></div>`}

function gallery(){return `<div class="kicker">COLLECTED MEMORIES</div><h1 class="resulttitle">みつやの記憶</h1><p class="introcopy">明るい夜も、寂しい夜も。<br>選んだ言葉の先にある風景を、少しずつ集めていこう。</p><p class="small">解放済み ${stored.unlocked.length} / 8 ・プレイ回数 ${stored.plays}。${stored.bestSpeed||'—'}文字/分が自己ベスト</p><div class="gallery">${ENDINGS.map((e,i)=>{let seen=stored.unlocked.includes(e.id);return `<button class="tile ${seen?'':'unseen'}" data-ending="${e.id}" ${seen?'':'disabled'}><img src="${esc(ART[e.id])}" loading="lazy" alt="${seen?esc(e.title):'未開放'}"><div class="tileinfo"><h3>${seen?esc(e.title):'？？？'}</h3><div class="small">${seen?e.type.toUpperCase():'LOCKED'}</div></div></button>`}).join('')}</div><p class="small">ヒント：みつやへの寄り添い方が違えば、異なる景色が現れます。静かな結末も、物語の一部です。</p><div class="btnrow"><button class="button" id="again">最初から話す</button><button class="button alt" id="album">風景アルバム</button><button class="button alt" id="home">タイトルへ</button></div>`}
function album(){const list=SCENE_ART_LIBRARY.slice(state.albumPage*10,state.albumPage*10+10);const seen=stored.seenArt||[];return `<div class="kicker">MEMORIES OF PLACES · 70 SCENES</div><h1 class="resulttitle">みつやと訪れた景色</h1><p class="introcopy">会話のたびに、違う空の下へ。<br>訪れた場所の絵をアルバムに残していこう。</p><p class="small">見つけた風景 ${seen.length}/70　·　${state.albumPage+1}/7 ページ<br>新しい10枚は、次の周回で解放されます。7周ですべての景色を巡れます。</p><div class="art-album">${list.map(a=>{const unlocked=seen.includes(a.id);return `<button class="art-card ${unlocked?'':'locked'}" ${unlocked?`data-art-id="${a.id}"`:'disabled'}><img src="${esc(a.src)}" alt="${unlocked?esc(a.title):'未解放の景色'}" loading="lazy"><span><small>SCENE ${a.id}</small><strong>${unlocked?esc(a.title):'まだ訪れていない場所'}</strong></span></button>`}).join('')}</div><div class="album-nav"><button class="button alt" id="album-prev" ${state.albumPage===0?'disabled':''}>← 前の10枚</button><span>${state.albumPage+1} / 7</span><button class="button alt" id="album-next" ${state.albumPage===6?'disabled':''}>次の10枚 →</button></div><div class="btnrow"><button class="button alt" id="home">タイトルへ</button><button class="button alt" id="gallery">エンディングを見る</button></div>`;}
function openEndingMedia(e){
 let movie=ENDING_MEDIA[e.id];
 const h=document.querySelector('#lightbox-host');
 let extra='';
 if(e.id==='HAPPY_CLOSENESS'){
  const opened=new Set(stored.bondEndings||[]);
  const levelButtons=[0,1,2,3].filter(n=>n===0||opened.has('HAPPY_CLOSENESS_'+n)).map(n=>`<button class="button alt" data-video-tier="${n}">親密Lv${n+1}</button>`).join('');
  extra=`<div class="btnrow">${levelButtons}</div>`;
  const maxTier=[3,2,1].find(n=>opened.has('HAPPY_CLOSENESS_'+n));if(maxTier!==undefined)movie=ENDING_MEDIA[e.id+'_'+maxTier]||movie;
 }
 const video=movie?`<video id="lb-ending-video" controls autoplay playsinline preload="metadata" poster="${esc(ART[e.id])}" style="width:min(90vw,880px);max-height:70vh"><source src="${esc(movie)}" type="video/mp4"></video>`:`<img src="${esc(ART[e.id])}" alt="${esc(e.title)}">`;
 h.innerHTML=`<div class="lightbox" role="dialog" aria-modal="true" aria-label="${esc(e.title)}">${video}<p class="small">${esc(e.title)} · エンディング動画</p>${extra}<div class="btnrow"><button class="button alt" id="lb-close">閉じる</button></div></div>`;
 h.querySelector('#lb-close').onclick=()=>h.innerHTML='';
 h.querySelectorAll('[data-video-tier]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.videoTier);const player=h.querySelector('#lb-ending-video');if(player){player.pause();player.src=ENDING_MEDIA[e.id+(n?'_'+n:'')]||ENDING_MEDIA[e.id];player.load();player.play().catch(()=>{});}});
 h.querySelector('.lightbox').onclick=ev=>{if(ev.target.classList.contains('lightbox'))h.innerHTML=''};
}
function openImage(src,title){const h=document.querySelector('#lightbox-host');h.innerHTML=`<div class="lightbox" role="dialog" aria-modal="true" aria-label="${esc(title)}"><img src="${esc(src)}" alt="${esc(title)}"><div class="btnrow"><button class="button" id="lb-save">画像を保存</button><button class="button alt" id="lb-close">閉じる</button></div></div>`;h.querySelector('#lb-close').onclick=()=>h.innerHTML='';h.querySelector('#lb-save').onclick=()=>download(src,title);h.querySelector('.lightbox').onclick=e=>{if(e.target.classList.contains('lightbox'))h.innerHTML=''};}
function download(path,name){let link=document.createElement('a');link.href=path;link.download=`mitsuya-${name.replace(/[^a-zA-Z0-9ぁ-んァ-ン一-龯ー]/g,'_')}.webp`;document.body.append(link);link.click();link.remove()}
function abortRun(){if(!confirm('プレイ中の進行を中断してスタート画面へ戻りますか？（解放済み画像と自己ベストは残ります）'))return;state=initial();render();window.scrollTo({top:0,behavior:'instant'});}
function bind(){const q=id=>document.getElementById(id);q('stop')?.addEventListener('click',abortRun);q('save-export')?.addEventListener('click',exportSave);q('save-import')?.addEventListener('change',e=>importSave(e.target.files?.[0]));q('start')?.addEventListener('click',startRun);q('again')?.addEventListener('click',startRun);q('home')?.addEventListener('click',()=>{state=initial();render()});q('gallery')?.addEventListener('click',()=>{state.page='gallery';render()});q('videos')?.addEventListener('click',()=>{state.page='videos';render()});q('auto-video')?.addEventListener('change',e=>setAutoVideo(e.target.checked));document.querySelectorAll('[data-memory]').forEach(b=>b.addEventListener('click',()=>{const v=videoLibrary().find(x=>x.id===b.dataset.memory&&x.unlocked);if(v)openVideoLightbox(v)}));q('album')?.addEventListener('click',()=>{state.page='album';state.albumPage=0;render()});q('album-prev')?.addEventListener('click',()=>{state.albumPage=Math.max(0,state.albumPage-1);render()});q('album-next')?.addEventListener('click',()=>{state.albumPage=Math.min(6,state.albumPage+1);render()});document.querySelectorAll('[data-art-id]').forEach(b=>b.addEventListener('click',()=>{const a=SCENE_ART_LIBRARY.find(a=>a.id===b.dataset.artId);if(a)openImage(a.src,a.title)}));document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));q('next')?.addEventListener('click',()=>{if(state.index===DATA.scenes.length-1)showEnd();else{state.index++;state.page='play';revealSceneArt();state.raw='';state.reply=null;state.typingStarted=0;state.sceneMistakes=0;render();showEventIfNeeded()}});q('save')?.addEventListener('click',()=>download(ART[state.ending.id],state.ending.id));q('open-result')?.addEventListener('click',()=>openImage(ART[state.ending.id],state.ending.title));document.querySelectorAll('[data-ending]').forEach(b=>b.addEventListener('click',()=>{const e=ENDINGS.find(x=>x.id===b.dataset.ending);openEndingMedia(e)}));const inp=q('typing');if(inp){compositionActive=false;inp.addEventListener('compositionstart',()=>{compositionActive=true});inp.addEventListener('compositionend',()=>{compositionActive=false;handleTyping()});inp.addEventListener('input',e=>{if(!compositionActive&&!e.isComposing)handleTyping()});inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&!compositionActive)e.preventDefault()})}}
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){const h=document.querySelector('#lightbox-host');h.querySelectorAll('video').forEach(p=>p.pause());h.innerHTML='';return;}
 if(e.key!=='Enter'||e.repeat||e.isComposing||compositionActive||e.keyCode===229)return;
 // Enter while composing only confirms Japanese IME input, not scene navigation.
 if(document.querySelector('#lightbox-host .story-video-modal')){e.preventDefault();document.getElementById('video-skip')?.click();return;}if(document.querySelector('#lightbox-host .lightbox'))return;
 if(state.page==='play')return;
 if(e.target.closest('button,summary,details,video,[contenteditable]'))return;
 if(state.page==='reply'){e.preventDefault();document.getElementById('next')?.click();}
 else if(state.page==='home'){e.preventDefault();document.getElementById('start')?.click();}
 else if(state.page==='result'){e.preventDefault();document.getElementById('again')?.click();}
});
render();
setInterval(tick,250);
